class Debouncer {
  /**
   * Creates a debouncer instance.
   * @param {function} asyncFunction - The async function to debounce.
   * @param {number} delay - The debounce delay in milliseconds.
   */
  constructor(asyncFunction, delay) {
    this.asyncFunction = asyncFunction;
    this.delay = delay;
    this.timeoutId = null;
    this.abortController = null;
  }

  /**
   * Debounces the async function call.
   * @param {...any} args - The arguments to pass to the async function.
   * @returns {Promise<any>} A promise that resolves with the result of the async function.
   */
  async debounce(...args) {
    // Cancel any ongoing request
    if (this.abortController) {
      this.abortController.abort();
    }

    // Create a new AbortController for the current request
    this.abortController = new AbortController();

    // Clear the existing timeout
    if (this.timeoutId) {
      globalThis.clearTimeout(this.timeoutId);
    }

    // Set a new timeout
    return new Promise((resolve, reject) => {
      this.timeoutId = globalThis.setTimeout(async () => {
        try {
          const result = await this.asyncFunction(...args, this.abortController.signal);
          resolve(result);
        } catch (error) {
          if (error.name === 'AbortError') {
            // Ignore AbortError
          } else {
            reject(error);
          }
        } finally {
          this.timeoutId = null;
          this.abortController = null;
        }
      }, this.delay);
    });
  }
}

